// Basic 3D Vector structure for kinematics
struct Vec3 {
    double x, y, z;

    Vec3 operator+(const Vec3& rhs) const { return {x + rhs.x, y + rhs.y, z + rhs.z}; }
    Vec3 operator-(const Vec3& rhs) const { return {x - rhs.x, y - rhs.y, z - rhs.z}; }
    Vec3 operator*(double scalar) const { return {x * scalar, y * scalar, z * scalar}; }

    double Length() const { return std::sqrt(x * x + y * y + z * z); }
    Vec3 Normalized() const { double len = Length(); return {x / len, y / len, z / len}; }
};

class SpacecraftPhysics {
public:
    Vec3 m_position = {0, 0, 0};
    Vec3 m_velocity = {0, 0, 100}; // Initial forward velocity
    double m_mass = 500.0;
    double m_acceleration = 0.0;

    // Apply Acceleration (Either programmatically or from pilot input)
    void ApplyThrust(double dt) {
        double deltaV = m_acceleration * dt;
        Vec3 thrustVec = m_velocity.Normalized(); // Thrust applies along facing axis
        m_velocity = m_velocity + (thrustVec * deltaV);
    }

    // Update position
    void Update(double dt) {
        ApplyThrust(dt);
        m_position = m_position + (m_velocity * dt);
    }
};

int main() {
    SpacecraftPhysics ship;
    ship.m_acceleration = 500.0;

    // Update kinematics for one second
    ship.Update(1.0);

    std::cout << "Final Position: " << ship.m_position.x << ", " << ship.m_position.y << ", " << ship.m_position.z << std::endl;
    return 0;
}
```

