import math
from decimal import Decimal, getcontext

# Set high precision for scientific calculations
getcontext().prec = 28

# --- TOOL: physics_formula_library ---
class PhysicsConstants:
    G_DECIMAL = Decimal('6.67430e-11')  # Gravitational Constant in m^3 kg^-1 s^-2
    UNIT_SYSTEMS = {
        'newton': ('N', 1),
        'dyne': ('dyn', 1e5),
        'pound_force': ('lbf', 0.224809)
    }

# --- TOOL: astronomy_database ---
CELESTIAL_BODIES = {
    "Sun": {"mass": Decimal('1.989e30'), "description": "Our Star"},
    "Earth": {"mass": Decimal('5.972e24'), "description": "Our Home"},
    "Moon": {"mass": Decimal('7.342e22'), "description": "Earth's Satellite"},
    "Jupiter": {"mass": Decimal('1.898e27'), "description": "Largest Planet"},
    "Mars": {"mass": Decimal('6.39e23'), "description": "Red Planet"},
    "Deimos": {"mass": Decimal('1.48e15'), "description": "Mars Moon"}
}

# --- TOOL: calculation_engine ---
class GravitationalForceCalculator:
    def calculate_force(self, mass1_kg, mass2_kg, distance_m):
        """
        Calculates gravitational force using Newton's Law.
        Uses Decimal for high precision.
        """
        if distance_m <= 0:
            raise ValueError("Distance must be greater than zero.")
        if mass1_kg <= 0 or mass2_kg <= 0:
            raise ValueError("Masses must be positive numbers.")

        m1 = Decimal(str(mass1_kg))
        m2 = Decimal(str(mass2_kg))
        r = Decimal(str(distance_m))

        # Formula: F = G * m1 * m2 / r^2
        force = PhysicsConstants.G_DECIMAL * m1 * m2 / (r ** 2)

        return force

    def convert_units(self, force_newtons, target_unit='newton'):
        """Converts Newtons to other unit systems."""
        if target_unit not in PhysicsConstants.UNIT_SYSTEMS:
            raise ValueError("Invalid unit requested.")

        symbol, multiplier = PhysicsConstants.UNIT_SYSTEMS[target_unit]
        # Convert Decimal force to float for display compatibility in some UIs
        force_float = float(force_newtons)

        return {
            "value": force_float * multiplier,
            "symbol": symbol
        }

# --- TOOL: validation_suite ---
class ValidationSuite:
