# Space Simulation Physics Engine

I'll develop a comprehensive physics engine for realistic space simulation with accurate gravitational calculations.

## Step 1: Implement the Core Physics Engine

Let's start by creating the core physics classes that will handle gravitational calculations and orbital mechanics.

```cpp
// physics_engine.h - Core physics engine for space simulation
#ifndef PHYSICS_ENGINE_H
#define PHYSICS_ENGINE_H

#include <vector>
#include <cmath>
#include <iostream>
#include <string>
#include <cassert>
#include <limits>

// Constants for gravitational simulation
namespace PhysicsConstants {
    static const double G = 6.67430e-11; // Gravitational constant in m³/(kg⋅s²)
    static const double AU = 1.496e11; // Astronomical Unit in meters
    static const double SUN_MASS = 1.989e30; // Solar mass in kg
    static const double SUN_RADIUS = 6.96e8; // Sun radius in meters
    static const double EARTH_MASS = 5.972e24; // Earth mass in kg
    static const double EARTH_RADIUS = 6.371e6; // Earth radius in meters
    static const double MOON_MASS = 7.342e22; // Moon mass in kg
    static const double MOON_ORBITAL_RADIUS = 3.844e8; // Moon-Earth distance in meters
    static const double MERCURY_MASS = 3.301e23;
    static const double VENUS_MASS = 4.867e24;
    static const double MARS_MASS = 6.417e23;
    static const double JUPITER_MASS = 1.898e27;
    static const double SATURN_MASS = 5.683e26;
    static const double URANUS_MASS = 8.681e25;
    static const double NEPTUNE_MASS = 1.024e26;

    // Orbital radii in meters
    static const double MERCURY_ORBITAL_RADIUS = 0.387 * AU;
    static const double VENUS_ORBITAL_RADIUS = 0.723 * AU;
    static const double EARTH_ORBITAL_RADIUS = 1.0 * AU;
    static const double MARS_ORBITAL_RADIUS = 1.524 * AU;
    static const double JUPITER_ORBITAL_RADIUS = 5.203 * AU;
    static const double SATURN_ORBITAL_RADIUS = 9.537 * AU;
    static const double URANUS_ORBITAL_RADIUS = 19.191 * AU;
    static const double NEPTUNE_ORBITAL_RADIUS = 30.069 * AU;

    // Simulation parameters
    static const double TIME_STEP = 86400.0; // 1 day in seconds
    static const double DENSITY_THRESHOLD_FACTOR = 0.1;
}

// Forward declaration
class Body;

// Three-dimensional vector class with vector operations
class Vector3D {
private:
    double x;
    double y;
    double z;

public:
    // Constructors
    Vector3D() : x(0), y(0), z(0) {}
    Vector3D(double x, double y, double z) : x(x), y(y), z(z) {}

    // Accessors
    double X() const { return x; }
    double Y() const { return y; }
    double Z() const { return z; }

    // Operators
    Vector3D operator+(const Vector3D& other) const {
        return Vector3D(x + other.x, y + other.y, z + other.z);
    }

    Vector3D operator-(const Vector3D& other) const {
        return Vector3D(x - other.x, y - other.y, z - other.z);
    }

    Vector3D operator*(double scalar) const {
        return Vector3D(x * scalar, y * scalar, z * scalar);
    }

    Vector3D operator/(double scalar) const {
        assert(std::abs(scalar) > 1e-10); // Prevent division by zero
        return Vector3D(x / scalar, y / scalar, z / scalar);
    }

    Vector3D operator-(const Vector3D& other) const {
        return Vector3D(x - other.x, y - other.y, z - other.z);
    }

    // Vector operations
    double Dot(const Vector3D& other) const {
        return x * other.x + y * other.y + z * other.z;
    }

    Vector3D Cross(const Vector3D& other) const {
        return Vector3D(
            y * other.z - z * other.y,
            z * other.x - x * other.z,
            x * other.y - y * other.x
        );
    }

    double Magnitude() const {
        return std::sqrt(x*x + y*y + z*z);
    }

    Vector3D Normalized() const {
        double mag = Magnitude();
        assert(mag > 1e-10); // Prevent division by zero
        return Vector3D(x/mag, y/mag, z/mag);
    }

    // Utility functions
    double DistanceTo(const Vector3D& other) const {
        Vector3D diff = *this - other;
        return diff.Magnitude();
    }

    void Print(const std::string& name = "") const {
        if (name.empty()) {
            std::cout << "(" << x << ", " << y << ", " << z << ")\n";
        } else {
            std::cout << name << ": (" << x << ", " << y << ", " << z << ")\n";
        }
    }
};

// Force calculations for gravity
Vector3D CalculateGravitationalForce(const Body& body1, const Body& body2) {
    Vector3D positionVector = body2.Position() - body1.Position();
    Vector3D directionVector = positionVector.Normalized();
    double distanceSquared = positionVector.Dot(positionVector);

    // Prevent division by zero with a minimum distance threshold
    double distance = std::sqrt(distanceSquared);
    const double MIN_DISTANCE = 1e6; // 1000 kilometers minimum distance
    if (distance < MIN_DISTANCE) {
        distance = MIN_DISTANCE;
        distanceSquared = MIN_DISTANCE * MIN_DISTANCE;
    }

    // Newton's law of universal gravitation: F = G * (m1 * m2) / r^2
    // Derived from F = ma where a is acceleration due to gravity
    double forceMagnitude = PhysicsConstants::G * body1.Mass() * body2.Mass() / distanceSquared;

    // Force direction is along the line connecting the two bodies
    Vector3D forceVector = directionVector * forceMagnitude;

    return forceVector;
}

// Acceleration calculation for a body
Vector3D CalculateAcceleration(const Body& body, const std::vector<Body>& bodies) {
    Vector3D totalForce(0, 0, 0);

    // Apply the superposition principle for multiple bodies
    for (const auto& otherBody : bodies) {
        if (&body != &otherBody) { // Avoid mutual force interaction
            totalForce += CalculateGravitationalForce(body, otherBody);
        }
    }

    // F = ma, so a = F/m
    return totalForce / body.Mass();
}

// Base class for all celestial bodies
class Body {
protected:
    std::string name;
    double mass; // in kg
    Vector3D position; // in meters
    Vector3D velocity; // in m/s

public:
    // Constructors
    Body() : mass(0), position(0, 0, 0), velocity(0, 0, 0) {}

    Body(const std::string& name, double mass, 
         double x, double y, double z, 
         double vx, double vy, double vz) :
         name(name), mass(mass), 
         position(x, y, z), 
         velocity(vx, vy, vz) {}

    // Accessors
    const std::string& Name() const { return name; }
    double Mass() const { return mass; }
    Vector3D Position() const { return position; }
    Vector3D Velocity() const { return velocity; }

    // Mutators
    void SetPosition(Vector3D pos) { position = pos; }
    void SetVelocity(Vector3D vel) { velocity = vel; }
    void SetName(const std::string& newName) { name = newName; }

    void Update(double timeStep) {
        Vector3D acceleration(0, 0, 0);
        // This will be calculated by the physics engine

        // Update velocity: v = v0 + a*t
        velocity = velocity + acceleration * timeStep;

        // Update position: x = x0 + v*t
        position = position + velocity * timeStep;
    }

    void PrintState() const {
        std::cout << name << ":\n";
        std::cout << "  Mass: " << mass << " kg\n";
        std::cout << "  Position: ";
        position.Print("  Position Vector");
        std::cout << "  Velocity: ";
        velocity.Print("  Velocity Vector");
    }

    double CalculateOrbitalPeriod(const Body& centralBody) const {
        double distance = Position().DistanceTo(centralBody.Position());

        // Kepler's third law: T² = (4π²/GM) * r³
        // T = 2π * sqrt(r³/GM)
        const double mu = PhysicsConstants::G * centralBody.Mass();
        return 2 * M_PI * std::pow(distance, 1.5) / std::sqrt(mu);
    }
};

// Specialized class for suns
class Sun : public Body {
private:
