// Spacecraft class (points or ships moving through the system)
class Spacecraft : public Body {
private:
    double fuel; // in kg
    double thrust; // in Newtons
    double maxThrust;

public:
    Spacecraft() : fuel(0), thrust(0), maxThrust(0) {}

    Spacecraft(const std::string& name, double mass, double fuel, double maxThrust) :
        Body(name, mass, 0, 0, 0, 0, 0, 0),
        fuel(fuel),
        thrust(0),
        maxThrust(maxThrust) {}

    void ApplyThrust(Vector3D direction) {
        if (fuel > 0) {
            thrust = std::min(maxThrust, fuel * 9.81); // Use specific impulse approximation
            fuel -= thrust * 86400.0 / 9.81; // Use time step as 1 day
        }
    }

    virtual void Update(double timeStep, const std::vector<Body>& bodies) {
        Body::Update(timeStep); // Use default update
    }

    void PrintState() const {
        Body::PrintState();
        std::cout << "  Fuel: " << fuel << " kg\n";
        std::cout << "  Thrust: " << thrust << " N\n";
        std::cout << "  Max Thrust: " << maxThrust << " N\n";
